function decodeB64Utf8(b64){const bin=atob(b64);const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return new TextDecoder().decode(bytes)}
function setActive(win){document.querySelectorAll('.window').forEach(w=>{w.classList.remove('active');const tb=w.querySelector('.titlebar');if(tb)tb.classList.add('inactive')});win.classList.add('active');win.style.zIndex=++topZ;const tb=win.querySelector('.titlebar');if(tb)tb.classList.remove('inactive')}
