function toggleMaximize(id){const win=document.getElementById(id);if(!win.dataset.restore&&!win.classList.contains('maximized')){win.dataset.restore=JSON.stringify({left:win.style.left,top:win.style.top,width:win.style.width,height:win.style.height});win.classList.add('maximized')}else{win.classList.remove('maximized');if(win.dataset.restore){Object.assign(win.style,JSON.parse(win.dataset.restore));delete win.dataset.restore}}setActive(win)}
function toggleStart(){document.getElementById('startMenu').classList.toggle('show')}
document.addEventListener('mousedown',e=>{const win=e.target.closest('.window');if(win)setActive(win);if(!e.target.closest('.start')&&!e.target.closest('.start-menu'))document.getElementById('startMenu').classList.remove('show')});
document.querySelectorAll('.window').forEach(win=>{const title=win.querySelector('.titlebar');let dragging=false,ox=0,oy=0;title.addEventListener('mousedown',e=>{if(e.target.tagName==='BUTTON')return;dragging=true;ox=e.clientX-win.offsetLeft;oy=e.clientY-win.offsetTop;setActive(win)});document.addEventListener('mousemove',e=>{if(!dragging||win.classList.contains('maximized'))return;win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,e.clientX-ox))+'px';win.style.top=Math.max(0,Math.min(innerHeight-36-win.offsetHeight,e.clientY-oy))+'px'});document.addEventListener('mouseup',()=>dragging=false)});
