async function saveNote(){const title=noteTitle.value.trim(),tag=noteTag.value.trim(),body=noteBody.value.trim();if(!title&&!body){setNoteStatus('Scrivi almeno titolo o testo');return}setNoteStatus('Salvataggio...');try{const res=await fetch(`${SUPABASE_URL}/rest/v1/${NOTES_TABLE}`,{method:'POST',headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${SUPABASE_ANON_KEY}`,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({title:title||null,tag:tag||null,body:body||null,source_app:'BatOS 3.14',user_agent:navigator.userAgent})});if(!res.ok)throw new Error(await res.text()||`HTTP ${res.status}`);setNoteStatus('Nota salvata su Supabase')}catch(err){setNoteStatus('Errore: '+err.message.slice(0,120))}}
async function loadNotes(){setNoteStatus('Caricamento...');try{const res=await fetch(`${SUPABASE_URL}/rest/v1/${NOTES_TABLE}?select=*&order=created_at.desc&limit=10`,{headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${SUPABASE_ANON_KEY}`}});if(!res.ok)throw new Error(await res.text()||`HTTP ${res.status}`);const rows=await res.json();noteBody.value=rows.map(r=>`[${new Date(r.created_at).toLocaleString('it-IT')}] ${r.title||'Senza titolo'}${r.tag?' #'+r.tag:''}\n${r.body||''}`).join('\n\n---\n\n');setNoteStatus(`${rows.length} note caricate`)}catch(err){setNoteStatus('Errore: '+err.message.slice(0,120))}}
