function byId(id){ return document.getElementById(id); }
function sheetStatus(html){ const el = byId('sheetSummary'); if (el) el.innerHTML = html; }
function getCell(cell){ return document.querySelector(`#batSheet td[data-cell="${cell}"]`); }
function rcToCell(r,c){ return COLS[c-1] + r; }
function colIndex(col){ return COLS.indexOf(String(col).toUpperCase()) + 1; }
function parseCellRef(ref){ const m = String(ref || '').trim().toUpperCase().match(/^([A-Z]+)(\d+)$/); if(!m) return null; const c = colIndex(m[1]); const r = Number(m[2]); return c && r ? {c,r,cell:m[1]+r} : null; }
function normalizeRange(txt){ const parts = String(txt || '').replace(/\s+/g,'').toUpperCase().split(':'); const a = parseCellRef(parts[0]); const b = parseCellRef(parts[1] || parts[0]); if(!a || !b) return null; return {r1:Math.min(a.r,b.r), r2:Math.max(a.r,b.r), c1:Math.min(a.c,b.c), c2:Math.max(a.c,b.c)}; }
function parseNumber(v){ const s = String(v ?? '').trim().replace(',', '.'); return s !== '' && !Number.isNaN(Number(s)) ? Number(s) : null; }
function fmt(n){ return n === null || n === undefined || Number.isNaN(n) ? '-' : Number(n).toLocaleString('it-IT', { maximumFractionDigits: 4 }); }
function median(a){ if(!a.length) return null; const x=[...a].sort((p,q)=>p-q), m=Math.floor(x.length/2); return x.length%2 ? x[m] : (x[m-1]+x[m])/2; }
function quantile(a,q){ if(!a.length) return null; const x=[...a].sort((p,q)=>p-q), pos=(x.length-1)*q, base=Math.floor(pos), rest=pos-base; return x[base+1]!==undefined ? x[base]+rest*(x[base+1]-x[base]) : x[base]; }
function mode(a){ const map=new Map(); a.forEach(n=>map.set(n,(map.get(n)||0)+1)); let max=0,out=[]; for(const [k,v] of map){ if(v>max){max=v;out=[k]} else if(v===max) out.push(k); } return max<=1 ? [] : out; }
function freqRaw(vals){ const map=new Map(); vals.filter(v=>v.raw!=='').forEach(v=>map.set(v.raw,(map.get(v.raw)||0)+1)); return [...map.entries()].sort((a,b)=>b[1]-a[1]).slice(0,12); }

function initSheet(){
  const table = byId('batSheet');
  if(!table || table.dataset.ready) return;
  let h = '<tr><th class="rowhead"></th>' + SHEET_COLS.map(([c,name]) => `<th>${c}<br><small>${name}</small></th>`).join('') + '</tr>';
  for(let r=1;r<=ROWS;r++){
    h += `<tr><th class="rowhead">${r}</th>` + COLS.map(c => `<td contenteditable="true" data-cell="${c}${r}"></td>`).join('') + '</tr>';
  }
  table.innerHTML = h;
  table.dataset.ready = '1';
  table.addEventListener('input', sheetChanged);
  table.addEventListener('focusin', e => { if(e.target.matches('td[data-cell]')) cellFocus(e.target.dataset.cell); });
  table.addEventListener('mousedown', e => { if(e.target.matches('td[data-cell]')) cellMouseDown(e, e.target.dataset.cell); });
  table.addEventListener('mouseover', e => { if(e.buttons && e.target.matches('td[data-cell]')) cellMouseEnter(e, e.target.dataset.cell); });
  resetSheetTemplate(false);
}
function resetSheetTemplate(showMsg=true){
  clearSheet(false);
  SHEET_DEMO_ROWS.forEach((row,i)=>writeObjectToSheetRow(i+2,row));
  const range = byId('rangeInput'); if(range) range.value = 'T2:T80';
  highlightRange('T2:T80');
  calcSelectedStat();
  if(showMsg) sheetStatus(byId('sheetSummary').innerHTML + '<span class="ok">Template Audiobat ripristinato</span>');
}
function clearSheet(showMsg=true){
  document.querySelectorAll('#batSheet td').forEach(td => td.textContent = '');
  lastSheetStats = null;
  if(showMsg) sheetStatus('<span>Foglio pulito</span>');
}
function sheetChanged(){ lastSheetStats = null; }
function writeObjectToSheetRow(rowNumber, obj){
  for(const [col,key] of SHEET_COLS){ const td=getCell(col+rowNumber); if(td) td.textContent = obj[key] ?? ''; }
}
function firstEmptyRow(){
  for(let r=2;r<=ROWS;r++){ if(COLS.every(c => !(getCell(c+r)?.textContent || '').trim())) return r; }
  return null;
}
function addAudiobatRows(payload){
  initSheet();
  openWindow('sheet');
  const rows = Array.isArray(payload?.rows) ? payload.rows : [];
  if(!rows.length){ sheetStatus('<span class="error">Audiobat non ha inviato righe valide</span>'); return; }
  let added=0, skipped=0;
  for(const row of rows){ const r=firstEmptyRow(); if(!r){ skipped++; continue; } writeObjectToSheetRow(r,row); added++; }
  const baseName = payload.file_wav ? payload.file_wav.replace(/\.[^.]+$/, '') : 'audiobat_import';
  const name = byId('sheetName'); if(name) name.value = baseName + '_stats';
  const range = byId('rangeInput'); if(range) range.value = added ? `T2:T${Math.min(ROWS, 1+added)}` : 'T2:T80';
  calcSelectedStat();
  sheetStatus(byId('sheetSummary').innerHTML + `<span class="ok">Importate ${added} righe da Audiobat</span>` + (skipped?`<span class="error">${skipped} righe non importate: foglio pieno</span>`:''));
}
window.addEventListener('message', ev => {
  if(ev.data && ev.data.type === 'AUDIOBAT_TO_BATSHEET') addAudiobatRows(ev.data.payload);
});
function selectRange(txt){ highlightRange(txt); const inp=byId('rangeInput'); if(inp) inp.value=txt; }
function highlightRange(txt){
  document.querySelectorAll('#batSheet td.sel').forEach(td => td.classList.remove('sel'));
  const r=normalizeRange(txt); if(!r) return;
  for(let rr=r.r1; rr<=r.r2; rr++) for(let cc=r.c1; cc<=r.c2; cc++){ const td=getCell(rcToCell(rr,cc)); if(td) td.classList.add('sel'); }
}
function cellFocus(cell){ selectionStart = selectionEnd = cell; const inp=byId('rangeInput'); if(inp) inp.value=cell; highlightRange(cell); }
function cellMouseDown(ev, cell){ selectionStart = selectionEnd = cell; const inp=byId('rangeInput'); if(inp) inp.value=cell; highlightRange(cell); }
function cellMouseEnter(ev, cell){ if(!selectionStart || !ev.buttons) return; selectionEnd = cell; const inp=byId('rangeInput'); if(inp) inp.value = `${selectionStart}:${selectionEnd}`; highlightRange(inp.value); }
function rangeValues(txt){
  highlightRange(txt);
  const r=normalizeRange(txt); if(!r) return [];
  const vals=[];
  for(let rr=r.r1; rr<=r.r2; rr++) for(let cc=r.c1; cc<=r.c2; cc++){ const cell=rcToCell(rr,cc), raw=(getCell(cell)?.textContent || '').trim(); vals.push({cell, raw, num:parseNumber(raw)}); }
  return vals;
}
function computeStats(vals){
  const nums=vals.map(v=>v.num).filter(n=>n!==null);
  const n=nums.length, sum=nums.reduce((a,b)=>a+b,0), mean=n?sum/n:null;
  const ss=n>1?nums.reduce((a,b)=>a+(b-mean)**2,0):0;
  const variance=n>1?ss/(n-1):null, stddev=variance!==null?Math.sqrt(variance):null;
  const med=median(nums), q1=quantile(nums,.25), q3=quantile(nums,.75), modes=mode(nums);
  const mad=med!==null?median(nums.map(x=>Math.abs(x-med))):null;
  return { count:n, text_count:vals.filter(v=>v.raw!=='').length, sum, mean, median:med, mode:modes, min:n?Math.min(...nums):null, max:n?Math.max(...nums):null, variance, stddev, q1, q3, iqr:q1!==null&&q3!==null?q3-q1:null, cv:mean?stddev/mean*100:null, mad, frequencies:freqRaw(vals) };
}
function calcSelectedStat(){
  const range = (byId('rangeInput')?.value || 'T2:T80').trim();
  const vals = rangeValues(range);
  if(!vals.length){ sheetStatus('<span class="error">Range non valido</span>'); return; }
  const st = computeStats(vals); lastSheetStats = { range, stats:st, computed_at:new Date().toISOString() };
  const op = byId('statSelect')?.value || 'all';
  let parts = [`<span>Range: ${range}</span>`, `<span>Valori numerici: ${st.count}</span>`, `<span>Celle compilate: ${st.text_count}</span>`];
  const add=(k,v)=>parts.push(`<span>${k}: ${v}</span>`);
  if(op==='all'||op==='mean')add('Media',fmt(st.mean));
  if(op==='all'||op==='median')add('Mediana',fmt(st.median));
  if(op==='all'||op==='mode')add('Moda',st.mode.length?st.mode.map(fmt).join(', '):'-');
  if(op==='all'||op==='stddev')add('Dev.std camp.',fmt(st.stddev));
  if(op==='all'||op==='variance')add('Varianza camp.',fmt(st.variance));
  if(op==='all'||op==='sum')add('Somma',fmt(st.sum));
  if(op==='all'||op==='minmax'){add('Min',fmt(st.min));add('Max',fmt(st.max));}
  if(op==='all'||op==='quartiles'){add('Q1',fmt(st.q1));add('Q3',fmt(st.q3));add('IQR',fmt(st.iqr));}
  if(op==='all'||op==='cv')add('CV %',fmt(st.cv));
  if(op==='all'||op==='mad')add('MAD',fmt(st.mad));
  if(op==='freq')add('Frequenze',st.frequencies.map(([k,v])=>`${k}:${v}`).join(' · ')||'-');
  sheetStatus(parts.join(''));
}
function sheetRowsArray(){
  const rows=[];
  for(let r=2;r<=ROWS;r++){ const row={}; let has=false; for(const [c,key] of SHEET_COLS){ const val=(getCell(c+r)?.textContent || '').trim(); row[key]=val; if(val) has=true; } if(has) rows.push(row); }
  return rows;
}
function sheetData(){ const cells={}; document.querySelectorAll('#batSheet td').forEach(td=>{cells[td.dataset.cell]=td.textContent.trim()}); return {headers:SHEET_HEADERS, rows:sheetRowsArray(), cells}; }
async function saveSheet(){
  calcSelectedStat();
  const nameEl=byId('sheetName');
  const payload={name:(nameEl?.value || '').trim() || 'audiobat sheet', grid:sheetData(), stats:lastSheetStats, last_stats:lastSheetStats, source_app:'BatOS 3.14', user_agent:navigator.userAgent};
  const old=byId('sheetSummary')?.innerHTML || '';
  sheetStatus(old + '<span>Salvataggio...</span>');
  try{
    const res=await fetch(`${SUPABASE_URL}/rest/v1/${SHEETS_TABLE}`,{method:'POST',headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${SUPABASE_ANON_KEY}`,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(payload)});
    const txt=await res.text(); if(!res.ok) throw new Error(txt || `HTTP ${res.status}`);
    sheetStatus(old + `<span class="ok">Salvato su Supabase (${res.status})</span>`);
  }catch(err){ sheetStatus(old + `<span class="error">Errore salvataggio: ${String(err.message).slice(0,260)}</span>`); }
}
function csvEscape(v){ v=String(v ?? ''); return /[";\n\r,]/.test(v) ? '"'+v.replaceAll('"','""')+'"' : v; }
function downloadText(filename,text,mime='text/csv;charset=utf-8'){ const blob=new Blob([String.fromCharCode(0xFEFF)+text],{type:mime}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),500); }
function exportSheetCsv(){
  const headers=SHEET_COLS.map(x=>x[1]);
  const lines=[headers.map(csvEscape).join(';')];
  for(const row of sheetRowsArray()) lines.push(headers.map(h=>csvEscape(row[h] || '')).join(';'));
  downloadText(((byId('sheetName')?.value || 'batsheet').trim() || 'batsheet')+'_dati.csv', lines.join('\n'));
  sheetStatus((byId('sheetSummary')?.innerHTML || '') + '<span class="ok">CSV dati esportato</span>');
}
function exportStatsCsv(){
  if(!lastSheetStats) calcSelectedStat();
  const st=lastSheetStats?.stats || {};
  const rows=[['metrica','valore'],['range',lastSheetStats?.range||''],['count',st.count],['text_count',st.text_count],['sum',st.sum],['mean',st.mean],['median',st.median],['mode',(st.mode||[]).join('|')],['variance',st.variance],['stddev',st.stddev],['min',st.min],['max',st.max],['q1',st.q1],['q3',st.q3],['iqr',st.iqr],['cv_percent',st.cv],['mad',st.mad],['frequencies',(st.frequencies||[]).map(x=>x[0]+':'+x[1]).join('|')]];
  downloadText(((byId('sheetName')?.value || 'batsheet').trim() || 'batsheet')+'_statistiche.csv', rows.map(r=>r.map(csvEscape).join(';')).join('\n'));
  sheetStatus((byId('sheetSummary')?.innerHTML || '') + '<span class="ok">CSV statistiche esportato</span>');
}
